-- PainelBotoes Mobile - versão ofuscada
-- O código original fica codificado neste arquivo.
local _d = ""
local _k = 173
local _o = {}

for _i = 1, #_d, 2 do
    local _v = tonumber(_d:sub(_i, _i + 1), 16)
    _o[#_o + 1] = string.char((_v - _k) % 256)
end

local _src = table.concat(_o)
local _fn = loadstring(_src)

if _fn then
    return _fn()
else
    error("loadstring nao esta disponivel neste executor")
end
